CREATE TRIGGER check_price
BEFORE INSERT ON products
FOR EACH ROW
BEGIN
  IF :NEW.price < 0 THEN
    RAISE_APPLICATION_ERROR(-20003, 'price cannot be negative');
  END IF;
END;
