CREATE TRIGGER log_changes
AFTER UPDATE ON products
BEGIN
  INSERT INTO audit_log VALUES (:OLD.id, :OLD.price, :NEW.price);
END;

-- BEFORE INSERT trigger: reject negative prices
IF :NEW.price < 0 THEN
  RAISE_APPLICATION_ERROR(-20003, 'bad price');
END IF;

